<?php
require_once "../includes/auth.php"; require_login("admin"); require_once "../config/db.php";
$msg="";
if(isset($_POST["save_result"])){ $sid=(int)$_POST["student_id"];$cid=(int)$_POST["course_id"];$marks=(float)$_POST["marks"];$grade=$_POST["grade"]; $stmt=$conn->prepare("INSERT INTO results(student_id,course_id,marks,grade) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE marks=VALUES(marks),grade=VALUES(grade)");$stmt->bind_param("iids",$sid,$cid,$marks,$grade);$stmt->execute();$msg="Result saved."; }
$students=$conn->query("SELECT id,full_name,student_id FROM users WHERE role='student' ORDER BY full_name");$courses=$conn->query("SELECT id,course_code,course_name FROM courses ORDER BY course_code");$rows=$conn->query("SELECT r.*,u.full_name,c.course_code FROM results r JOIN users u ON r.student_id=u.id JOIN courses c ON r.course_id=c.id ORDER BY r.id DESC");
$page_title="Results";$css_path="../assets/css/style.css";$js_path="../assets/js/main.js";require "../includes/header.php";
?>
<div class="dashboard"><aside class="sidebar"><?php include "sidebar.php"; ?></aside><main class="dash-main"><h1>Result Management</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?>
<div class="panel"><h2>Enter Result</h2><form method="POST" class="form-grid"><select name="student_id" required><option value="">Student</option><?php while($s=$students->fetch_assoc()):?><option value="<?=$s["id"]?>"><?=e($s["student_id"]." - ".$s["full_name"])?></option><?php endwhile;?></select><select name="course_id" required><option value="">Course</option><?php while($c=$courses->fetch_assoc()):?><option value="<?=$c["id"]?>"><?=e($c["course_code"]." - ".$c["course_name"])?></option><?php endwhile;?></select><input type="number" step=".01" min="0" max="100" name="marks" placeholder="Marks" required><select name="grade"><option>A+</option><option>A</option><option>A-</option><option>B+</option><option>B</option><option>C+</option><option>C</option><option>D</option><option>F</option></select><button name="save_result" class="btn btn-primary">Save Result</button></form></div>
<div class="panel"><h2>Recent Results</h2><div class="table-wrap"><table><tr><th>Student</th><th>Course</th><th>Marks</th><th>Grade</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["full_name"])?></td><td><?=e($r["course_code"])?></td><td><?=$r["marks"]?></td><td><b><?=e($r["grade"])?></b></td></tr><?php endwhile;?></table></div></div></main></div><?php require "../includes/footer.php"; ?>